def clean(df):
    df = df.copy()

    # Normalize text fields
    for col in ['Date', 'Product', 'Category', 'Region']:
        if col in df.columns:
            df[col] = df[col].astype('string').str.strip()

    if 'Region' in df.columns:
        df['Region'] = df['Region'].str.title()
        df['Region'] = df['Region'].replace({'': pd.NA})

    # Ensure numeric fields are numeric
    for col in ['Quantity', 'Price', 'Revenue']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')

    # Fix negative quantities (sign errors) and recompute revenue
    if 'Quantity' in df.columns:
        df['Quantity'] = df['Quantity'].abs()

    if {'Quantity', 'Price', 'Revenue'}.issubset(df.columns):
        df['Revenue'] = df['Quantity'] * df['Price']

    # Remove exact duplicate records
    df = df.drop_duplicates()

    # Keep valid rows for price analysis
    if 'Price' in df.columns:
        df = df[df['Price'].notna() & (df['Price'] >= 0)]
    if 'Quantity' in df.columns:
        df = df[df['Quantity'].notna() & (df['Quantity'] >= 1)]

    return df


def answer(df):
    d = clean(df)
    d = d.dropna(subset=['Category', 'Price'])
    out = d.groupby('Category', dropna=True)['Price'].mean()
    return {str(k): float(v) for k, v in out.items()}
